1	import Link from "next/link";
2	import {
3	  ArrowRight, CheckCircle2, Eye, FileSignature, FolderKanban, Heart, Inbox, KeyRound, LandPlot, MailWarning, MessagesSquare, Sparkles,
4	} from "lucide-react";
5	import Button from "@/components/ui/Button";
6	import KpiKachel from "@/components/ui/KpiKachel";
7	import Stagger from "@/components/ui/Stagger";
8	import { Badge, Hinweis, Karte, Leer, PfeilLink, SeitenKopf, StatusBadge, Stepper } from "@/components/Portal/ui";
9	import { KeineFlaechen, KeineNachrichten, KeineProjekte, KeineDokumente, SucheOhneTreffer } from "@/components/illustrationen";
10	import { portalNutzer, istAdmin } from "@/lib/plattform/server/seite";
11	import { backend } from "@/lib/plattform/backend";
12	import { rolleLabel, VORGANG_TYPEN, PROJEKT_TYPEN, LAENDER } from "@/lib/plattform/konstanten";
13	import { statusLabel } from "@/lib/plattform/prozesse";
14	import { datum, ha, mwp, preisText, relativ } from "@/lib/plattform/format";
15	import { fmt } from "@/lib/rechner/annahmen";
16	import { phaseById } from "@/lib/invest/markt";
17	import ErsteSchritte from "@/components/Portal/Bedienung/Onboarding/ErsteSchritte";
18	import { pfad } from "@/lib/land";
19	import { BriefcaseBusiness } from "lucide-react"; // Portfolio
20	import { portfolioBackend } from "@/lib/plattform/backend/portfolio"; // Portfolio
21	
22	// Die Vorlage „%s | Portal ÖkoInvest“ greift nur für Unterseiten – hier daher absolut (einheitliche Tab-Titel)
23	export const metadata = { title: { absolute: "Übersicht | Portal ÖkoInvest" } };
24	
25	const ZEITZONE = "Europe/Berlin";
26	
27	/** Begrüßung nach Tageszeit (Server, Zeitzone des Unternehmens) */
28	function begruessung(jetzt = new Date()) {
29	  const stunde = Number(new Intl.DateTimeFormat("de-DE", { hour: "numeric", hourCycle: "h23", timeZone: ZEITZONE }).format(jetzt));
30	  if (stunde >= 5 && stunde < 11) return "Guten Morgen";
31	  if (stunde >= 11 && stunde < 18) return "Guten Tag";
32	  return "Guten Abend";
33	}
34	
35	/** Anzahl je Kalenderwoche (älteste zuerst) – für Mini-Verläufe */
36	function jeWoche(liste, feld, wochen = 8) {
37	  const jetzt = Date.now();
38	  const werte = new Array(wochen).fill(0);
39	  for (const x of liste) {
40	    const t = new Date(x[feld]).getTime();
41	    if (!Number.isFinite(t)) continue;
42	    const i = Math.floor((jetzt - t) / (7 * 864e5));
43	    if (i >= 0 && i < wochen) werte[wochen - 1 - i] += 1;
44	  }
45	  return werte;
46	}
47	
48	export default async function PortalStart({ searchParams }) {
49	  const n = await portalNutzer();
50	  const sp = await searchParams;
51	  const b = backend();
52	  // Rollenbereiche nur für tatsächlich gewählte Rollen (Admin sieht sein Cockpit separat)
53	  const hat = (...r) => r.some((x) => n.rollen.includes(x));
54	  const flaecheRolle = hat("flaeche", "landwirt");
55	  const anbieter = hat("anbieter");
56	  const investor = hat("investor");
57	  const admin = istAdmin(n);
58	
59	  const [vorgaenge, flaechen, projekte, interessen, boerse, threads, uebersicht] = await Promise.all([
60	    b.vorgaenge(n),
61	    flaecheRolle ? b.flaechen(n) : [],
62	    anbieter ? b.projekte(n) : [],
63	    investor ? b.interessen(n) : [],
64	    investor ? b.boerse(n) : null,
65	    b.nachrichtenThreads(n),
66	    admin ? b.adminUebersicht(n) : null,
67	  ]);
68	
69	  const ungelesen = threads.reduce((s, t) => s + t.ungelesen, 0);
70	  const offeneVorgaenge = vorgaenge.filter((v) => !["abgeschlossen", "abgelehnt", "zurueckgezogen"].includes(v.status));
71	  const passende = investor && boerse ? boerse.projekte.filter((p) => p.matching).sort((a, c) => c.matching.score - a.matching.score).slice(0, 3) : [];
72	  const datenraeume = interessen.filter((i) => ["nda_freigegeben", "loi_abgegeben", "loi_angenommen"].includes(i.status));
73	  const merkliste = interessen.filter((i) => i.gemerkt);
74	
75	  // ---------------------------------------------------------------- Als Nächstes (nach Dringlichkeit)
76	  // prio: 1 = Entscheidung liegt bei Ihnen, 2 = Weg fortsetzen, 3 = Einrichtung/Hinweis
77	  const schritte = [];
78	  for (const f of flaechen.filter((x) => x.status === "pachtangebot")) schritte.push({ prio: 1, icon: FileSignature, titel: `Ihr Pachtangebot für „${f.bezeichnung}“ liegt vor`, text: "Eckdaten prüfen, dann annehmen oder eine Rückfrage stellen. Sie entscheiden ohne Zeitdruck.", href: `/portal/flaechen/${f.id}`, cta: "Angebot jetzt prüfen" });
79	  for (const i of interessen.filter((x) => x.status === "nda_freigegeben")) schritte.push({ prio: 1, icon: KeyRound, titel: `Datenraum offen: ${i.projekt?.titel}`, text: "Unterlagen prüfen und bei Interesse eine LOI abgeben.", href: `/portal/boerse/${i.projektId}`, cta: "Zum Datenraum" });
80	  if (ungelesen) schritte.push({ prio: 2, icon: MessagesSquare, titel: `${ungelesen} ungelesene Nachricht${ungelesen === 1 ? "" : "en"}`, text: "Das Backoffice hat Ihnen geschrieben.", href: "/portal/nachrichten", cta: "Lesen" });
81	  for (const f of flaechen.filter((x) => x.status === "entwurf")) schritte.push({ prio: 2, icon: LandPlot, titel: `Fläche vervollständigen: ${f.bezeichnung}`, text: "Ergänzen Sie Ort und Größe und reichen Sie die Fläche zur Prüfung ein.", href: `/portal/flaechen/${f.id}`, cta: "Fläche ergänzen", dauer: "ca. 3 Min." });
82	  for (const p of projekte.filter((x) => x.status === "entwurf")) schritte.push({ prio: 2, icon: FolderKanban, titel: `Projekt einreichen: ${p.titel}`, text: p.provisionAkzeptiert ? "Angaben prüfen und zur Freigabe einreichen." : "Provisionsvereinbarung akzeptieren und einreichen.", href: `/portal/projekte/${p.id}`, cta: "Zum Projekt" });
83	  if (flaecheRolle && !flaechen.length) schritte.push({ prio: 2, icon: LandPlot, titel: "Erste Fläche hinzufügen", text: "Lage, Größe und Flurstücke genügen für eine kostenlose Vorprüfung.", href: "/portal/flaechen/neu", cta: "Fläche hinzufügen", dauer: "ca. 2 Min." });
84	  if (anbieter && !projekte.length) schritte.push({ prio: 2, icon: FolderKanban, titel: "Erstes Projekt anlegen", text: "Anonymer Teaser, vertraulicher Datenraum – Provision nur bei Abschluss.", href: "/portal/projekte/neu", cta: "Projekt anlegen" });
85	  if (investor && !n.suchprofil) schritte.push({ prio: 2, icon: Sparkles, titel: "Suchprofil anlegen", text: "Wir zeigen Ihnen passende Projekte mit Matching-Score.", href: "/portal/profil#suchprofil", cta: "Suchprofil anlegen", dauer: "ca. 2 Min." });
86	  if (!n.emailBestaetigt) schritte.push({ prio: 3, icon: MailWarning, titel: "E-Mail-Adresse bestätigen", text: "Danach ordnen wir frühere Anfragen mit Ihrer Adresse automatisch zu.", href: "/portal/profil", cta: "Mehr erfahren" });
87	  schritte.sort((a, c) => a.prio - c.prio);
88	  const [erster, ...weitere] = schritte;
89	
90	  // ---------------------------------------------------------------- Kennzahlen
91	  const kacheln = [];
92	  if (flaecheRolle) kacheln.push({ label: "Flächen", wert: flaechen.length, hinweis: `${ha(flaechen.reduce((s, f) => s + (f.ha || 0), 0))} insgesamt`, icon: LandPlot, href: "/portal/flaechen" });
93	  if (anbieter) {
94	    kacheln.push({ label: "Projekte in der Börse", wert: projekte.filter((p) => ["veroeffentlicht", "reserviert"].includes(p.status)).length, hinweis: `${fmt(projekte.length)} Projekte gesamt`, icon: FolderKanban, href: "/portal/projekte" });
95	    kacheln.push({ label: "Aufrufe & Merker", wert: projekte.reduce((s, p) => s + p.statistik.aufrufe, 0), hinweis: `${fmt(projekte.reduce((s, p) => s + p.statistik.merker, 0))} Merker · ${fmt(projekte.reduce((s, p) => s + p.statistik.ndaAnfragen, 0))} NDA-Anfragen`, icon: Eye, href: "/portal/projekte" });
96	  }
97	  if (investor) {
98	    kacheln.push({ label: "Passende Projekte", wert: boerse?.projekte.filter((p) => (p.matching?.score || 0) >= 70).length || 0, hinweis: n.suchprofil ? "Matching-Score ≥ 70" : "Suchprofil fehlt", icon: Sparkles, href: "/portal/boerse?sortierung=passung" });
99	    kacheln.push({ label: "Merkliste", wert: merkliste.length, hinweis: `${fmt(datenraeume.length)} Datenräume frei`, icon: Heart, href: "/portal/boerse?ansicht=merkliste" });
100	    const pf = await portfolioBackend().pfMeine(n).catch(() => null); // Portfolio: Positionen nach dem Kauf
101	    if (pf?.positionen.length) kacheln.push({ label: "Portfolio", wert: pf.kennzahlen.anzahl, hinweis: pf.kennzahlen.offeneAbrufe ? `${fmt(pf.kennzahlen.offeneAbrufe)} Kapitalabruf(e) offen` : `${fmt(pf.kennzahlen.mwp)} MWp anteilig`, icon: BriefcaseBusiness, href: "/portal/portfolio" });
102	  }
103	  const anfragenVerlauf = vorgaenge.length >= 3 ? jeWoche(vorgaenge, "erstelltAm") : null;
104	  kacheln.push({ label: "Offene Anfragen", wert: offeneVorgaenge.length, hinweis: anfragenVerlauf ? `${fmt(vorgaenge.length)} gesamt · 8 Wochen` : `${fmt(vorgaenge.length)} gesamt`, icon: Inbox, href: "/portal/anfragen", verlauf: anfragenVerlauf?.some(Boolean) ? anfragenVerlauf : undefined });
105	  kacheln.push({ label: "Ungelesene Nachrichten", wert: ungelesen, hinweis: `${fmt(threads.length)} ${threads.length === 1 ? "Unterhaltung" : "Unterhaltungen"}`, icon: MessagesSquare, href: "/portal/nachrichten" });
106	
107	  // ---------------------------------------------------------------- Aktivität
108	  const aktivitaet = [
109	    ...flaechen.flatMap((f) => (f.statusVerlauf || []).map((e) => ({ ...e, art: "flaeche", titel: f.bezeichnung, href: `/portal/flaechen/${f.id}` }))),
110	    ...projekte.flatMap((p) => (p.statusVerlauf || []).map((e) => ({ ...e, art: "projekt", titel: p.titel, href: `/portal/projekte/${p.id}` }))),
111	    ...interessen.flatMap((i) => (i.statusVerlauf || []).map((e) => ({ ...e, art: "interesse", titel: i.projekt?.titel || i.projektId, href: `/portal/boerse/${i.projektId}` }))),
112	    ...vorgaenge.map((v) => ({ status: v.status, am: v.geaendertAm, art: "vorgang", titel: `Anfrage ${VORGANG_TYPEN[v.typ]}`, href: `/portal/anfragen/${v.id}`, kommentar: v.letzterKommentar })),
113	  ]
114	    .sort((a, c) => String(c.am).localeCompare(String(a.am)))
115	    .slice(0, 7);
116	
117	  const hinweis = sp?.hinweis;
118	  const heute = new Intl.DateTimeFormat("de-DE", { weekday: "long", day: "numeric", month: "long", timeZone: ZEITZONE }).format(new Date());
119	  const offenText = !erster
120	    ? "Heute ist nichts von Ihnen zu tun – wir melden uns, sobald es weitergeht."
121	    : schritte.length === 1
122	      ? "Ein Punkt wartet auf Sie. Alles Weitere sehen Sie darunter."
123	      : `${schritte.length} Punkte warten auf Sie – der wichtigste steht oben.`;
124	  const ErsterIcon = erster?.icon;
125	
126	  return (
127	    <div className="space-y-6 md:space-y-8">
128	      <SeitenKopf
129	        eyebrow={heute}
130	        titel={`${begruessung()}, ${n.vorname}`}
131	        text={offenText}
132	        aktionen={
133	          <div className="flex flex-wrap gap-1.5">
134	            {n.rollen.map((r) => (
135	              <Badge key={r} ton={r === "admin" ? "dunkel" : "neutral"}>{rolleLabel(r)}</Badge>
136	            ))}
137	          </div>
138	        }
139	      />
140	
141	      {hinweis === "email-bestaetigt" && <Hinweis ton="ok" titel="E-Mail-Adresse bestätigt">Vielen Dank. Frühere Anfragen mit dieser Adresse sind jetzt Ihrem Konto zugeordnet.</Hinweis>}
142	      {hinweis === "willkommen" && <Hinweis ton="ok" titel="Willkommen im Portal">Ihr Konto ist angelegt. Hier verfolgen Sie ab sofort alle Schritte.</Hinweis>}
143	      {hinweis === "einstieg-fertig" && <Hinweis ton="ok" titel="Einstieg abgeschlossen">Ihr Portal ist eingerichtet. Tipp: Mit Strg + K (Mac: ⌘ + K) finden Sie alles in Sekunden.</Hinweis>}
144	
145	      {/* Als Nächstes – die eine dunkle Karte dieser Ansicht */}
146	      <section aria-labelledby="als-naechstes" className="ov-ein ov-verlauf-nacht relative overflow-hidden rounded-3xl p-6 text-white shadow-e3 ring-1 ring-white/10 md:p-8" style={{ "--ov-delay": "60ms" }}>
147	        <div className="flex flex-wrap items-center justify-between gap-3">
148	          <h2 id="als-naechstes" className="ov-overline text-ov-300">Als Nächstes</h2>
149	          {schritte.length > 1 && <Badge ton="dunkel" groesse="sm">{schritte.length} offen</Badge>}
150	        </div>
151	        {erster ? (
152	          <>
153	            <div className="mt-5 flex flex-col gap-5 md:flex-row md:items-center">
154	              <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-white/10 text-ov-300 ring-1 ring-white/10">
155	                <ErsterIcon aria-hidden="true" className="h-6 w-6" strokeWidth={1.8} />
156	              </span>
157	              <div className="min-w-0 flex-1">
158	                <p className="font-display text-[clamp(1.15rem,1.05rem+0.45vw,1.45rem)] font-bold leading-snug tracking-[-0.015em]">{erster.titel}</p>
159	                <p className="mt-1.5 max-w-2xl text-[14.5px] leading-relaxed text-white/75">
160	                  {erster.text}
161	                  {erster.dauer && <span className="ml-1.5 whitespace-nowrap text-white/75">· {erster.dauer}</span>}
162	                </p>
163	              </div>
164	              <Button href={erster.href} variant="primary" pfeil className="shrink-0 self-start md:self-center">
165	                {erster.cta}
166	              </Button>
167	            </div>
168	            {weitere.length > 0 && (
169	              <div className="mt-6 border-t border-white/10 pt-4">
170	                <p className="text-[12.5px] font-semibold text-white/75">Danach</p>
171	                <Stagger as="ul" className="mt-2 grid gap-2 md:grid-cols-2" delay={120}>
172	                  {weitere.slice(0, 4).map((s, i) => {
173	                    const Icon = s.icon;
174	                    return (
175	                      <li key={`${s.titel}-${i}`}>
176	                        <Link href={s.href} className="group flex items-center gap-3 rounded-2xl bg-white/[0.05] p-3 ring-1 ring-white/10 transition-colors duration-150 hover:bg-white/[0.09] hover:ring-white/20">
177	                          <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white/10 text-ov-300">
178	                            <Icon aria-hidden="true" className="h-[18px] w-[18px]" />
179	                          </span>
180	                          <span className="min-w-0 flex-1">
181	                            <span className="block truncate text-[14px] font-semibold">{s.titel}</span>
182	                            <span className="block truncate text-[12.5px] text-white/75">{s.cta}</span>
183	                          </span>
184	                          <ArrowRight aria-hidden="true" className="h-4 w-4 shrink-0 text-white/60 transition-transform duration-150 group-hover:translate-x-0.5 group-hover:text-white" />
185	                        </Link>
186	                      </li>
187	                    );
188	                  })}
189	                </Stagger>
190	                {weitere.length > 4 && <p className="mt-3 text-[12.5px] text-white/75">… und {weitere.length - 4} weitere – alle Vorgänge unter <Link href="/portal/anfragen" className="font-semibold text-white underline underline-offset-2">Meine Anfragen</Link>.</p>}
191	              </div>
192	            )}
193	          </>
194	        ) : (
195	          <div className="mt-5 flex flex-col gap-4 sm:flex-row sm:items-center">
196	            <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-ov-300/15 text-ov-300 ring-1 ring-ov-300/20">
197	              <CheckCircle2 aria-hidden="true" className="h-6 w-6" strokeWidth={1.8} />
198	            </span>
199	            <div className="min-w-0 flex-1">
200	              <p className="font-display text-[20px] font-bold leading-snug">Alles erledigt</p>
201	              <p className="mt-1 text-[14.5px] leading-relaxed text-white/75">Aktuell ist nichts von Ihnen zu tun. Wir melden uns, sobald es weitergeht.</p>
202	            </div>
203	            <Button href="/portal/anfragen" variant="outlineLight" size="sm">Anfragen ansehen</Button>
204	          </div>
205	        )}
206	      </section>
207	
208	      <Stagger className={`grid grid-cols-2 gap-3 md:gap-4 ${kacheln.length >= 4 ? "xl:grid-cols-4" : "lg:grid-cols-3"}`}>
209	        {kacheln.slice(0, 4).map((k) => (
210	          <KpiKachel key={k.label} {...k} />
211	        ))}
212	      </Stagger>
213	
214	      {/* Einarbeitung unter der nächsten Aktion, damit sie den ersten Bildschirm nicht belegt */}
215	      <ErsteSchritte nutzer={n} />
216	
217	      <div className="grid gap-6 lg:grid-cols-[minmax(0,1.6fr)_minmax(0,1fr)]">
218	        <div className="min-w-0 space-y-6">
219	          {admin && uebersicht && (
220	            <Karte titel="Backoffice" untertitel="Was heute auf dem Tisch liegt" aktion={<PfeilLink href="/portal/admin">Zum Cockpit</PfeilLink>}>
221	              <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
222	                {[
223	                  { label: "Neue Vorgänge (7 Tage)", wert: uebersicht.vorgaenge.neu7, href: "/portal/admin/vorgaenge?status=eingegangen" },
224	                  { label: "Projekte in Prüfung", wert: uebersicht.projekte.inPruefung, href: "/portal/admin/projekte" },
225	                  { label: "NDA-Anfragen offen", wert: uebersicht.interessen.ndaOffen, href: "/portal/admin/interessen" },
226	                  { label: "Ungelesene Nachrichten", wert: uebersicht.nachrichten.ungelesen, href: "/portal/nachrichten" },
227	                ].map((k) => (
228	                  <Link key={k.label} href={k.href} className="ov-lift ov-press rounded-2xl bg-sand-50 p-4 ring-1 ring-ink-200/60 hover:ring-ov-300">
229	                    <p className="ov-kpi text-ink-900">{fmt(k.wert)}</p>
230	                    <p className="mt-1 text-[12.5px] leading-snug text-ink-600">{k.label}</p>
231	                  </Link>
232	                ))}
233	              </div>
234	            </Karte>
235	          )}
236	
237	          {flaecheRolle && (
238	            <Karte titel="Meine Flächen" icon={LandPlot} aktion={<PfeilLink href="/portal/flaechen">Alle Flächen</PfeilLink>}>
239	              {flaechen.length ? (
240	                <ul className="space-y-5">
241	                  {flaechen.slice(0, 4).map((f) => (
242	                    <li key={f.id}>
243	                      <div className="flex flex-wrap items-center justify-between gap-2">
244	                        <Link href={`/portal/flaechen/${f.id}`} className="font-semibold text-ink-900 hover:text-ov-700">{f.bezeichnung}</Link>
245	                        <StatusBadge art="flaeche" status={f.status} />
246	                      </div>
247	                      <p className="mb-2.5 mt-0.5 text-[13px] text-ink-500">{[ha(f.ha), [f.plz, f.ort].filter(Boolean).join(" "), f.agri ? "Agri-PV" : null].filter(Boolean).join(" · ")}</p>
248	                      <Stepper art="flaeche" status={f.status} kompakt />
249	                    </li>
250	                  ))}
251	                </ul>
252	              ) : (
253	                <Leer illustration={<KeineFlaechen />} titel="Noch keine Fläche" text="Fügen Sie Ihre erste Fläche hinzu – die Vorprüfung ist kostenlos und dauert etwa zwei Minuten." aktion={<Button href="/portal/flaechen/neu" size="sm" pfeil>Fläche hinzufügen</Button>} />
254	              )}
255	            </Karte>
256	          )}
257	
258	          {anbieter && (
259	            <Karte titel="Meine Projekte" icon={FolderKanban} aktion={<PfeilLink href="/portal/projekte">Alle Projekte</PfeilLink>}>
260	              {projekte.length ? (
261	                <ul className="divide-y divide-ink-100">
262	                  {projekte.slice(0, 5).map((p) => (
263	                    <li key={p.id} className="flex flex-col gap-2 py-3 first:pt-0 last:pb-0 sm:flex-row sm:items-center">
264	                      <div className="min-w-0 flex-1">
265	                        <Link href={`/portal/projekte/${p.id}`} className="font-semibold text-ink-900 hover:text-ov-700">{p.titel}</Link>
266	                        <p className="text-[13px] text-ink-500">{[PROJEKT_TYPEN[p.typ], mwp(p.mwp), phaseById(p.phase)?.kurz].filter(Boolean).join(" · ")}</p>
267	                      </div>
268	                      <p className="flex gap-3 text-[12.5px] text-ink-500">
269	                        <span><Eye aria-hidden="true" className="mr-1 inline h-3.5 w-3.5" /><span className="sr-only">Aufrufe </span>{fmt(p.statistik.aufrufe)}</span>
270	                        <span><Heart aria-hidden="true" className="mr-1 inline h-3.5 w-3.5" /><span className="sr-only">Merker </span>{fmt(p.statistik.merker)}</span>
271	                        <span><KeyRound aria-hidden="true" className="mr-1 inline h-3.5 w-3.5" /><span className="sr-only">NDA-Anfragen </span>{fmt(p.statistik.ndaAnfragen)}</span>
272	                      </p>
273	                      <StatusBadge art="projekt" status={p.status} />
274	                    </li>
275	                  ))}
276	                </ul>
277	              ) : (
278	                <Leer illustration={<KeineProjekte />} titel="Noch kein Projekt" text="Stellen Sie Ihr erstes Projekt in die Börse – geprüft und vertraulich." aktion={<Button href="/portal/projekte/neu" size="sm" pfeil>Projekt anlegen</Button>} />
279	              )}
280	            </Karte>
281	          )}
