// Rollen-Tour: je Demo-Rolle anmelden, Übersicht + Hauptarbeitsseite aufnehmen, Fehler sammeln.
// Aufruf: node rollen-tour.mjs [nurRolle]
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const BASIS = "http://localhost:3100";
const PASS = "Demo-2026!";
const OUT = new URL("./shots-rollen/", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
mkdirSync(OUT, { recursive: true });

const ROLLEN = [
  { key: "flaeche", email: "flaeche@example.com", seiten: ["/portal", "/portal/flaechen"] },
  { key: "landwirt", email: "landwirt@example.com", seiten: ["/portal", "/portal/flaechen"] },
  { key: "investor", email: "investor@example.com", seiten: ["/portal", "/portal/boerse"] },
  { key: "anbieter", email: "anbieter@example.com", seiten: ["/portal", "/portal/projekte"] },
  { key: "unternehmen", email: "unternehmen@example.com", seiten: ["/portal", "/portal/energie"] },
  { key: "mitglied", email: "mitglied@example.com", seiten: ["/portal", "/portal/beteiligung"] },
  { key: "kommune", email: "kommune@example.com", seiten: ["/portal", "/portal/kommune"] },
  { key: "bank", email: "bank@example.com", seiten: ["/portal", "/portal/bank"] },
  { key: "gutachter", email: "gutachter@example.com", seiten: ["/portal", "/portal/gutachter"] },
  { key: "lieferant", email: "lieferant@example.com", seiten: ["/portal", "/portal/ausschreibungen"] },
  { key: "admin", email: "admin@example.com", seiten: ["/portal/admin"] },
  { key: "bo-compliance", email: "bo-compliance@example.com", seiten: ["/portal/admin/compliance"] },
  { key: "bo-betrieb", email: "bo-betrieb@example.com", seiten: ["/portal/admin/anlagen"] },
];

const nur = process.argv[2];
const browser = await chromium.launch();
try {
  for (const r of ROLLEN) {
    if (nur && r.key !== nur) continue;
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    const fehler = [];
    page.on("console", (m) => m.type() === "error" && fehler.push(m.text().slice(0, 200)));
    page.on("pageerror", (e) => fehler.push(String(e).slice(0, 200)));
    try {
      await page.goto(`${BASIS}/login`, { waitUntil: "load", timeout: 180000 });
      await page.fill('input[type="email"], input[name="email"]', r.email);
      await page.fill('input[type="password"], input[name="passwort"], input[name="password"]', PASS);
      await page.click('button[type="submit"]');
      await page.waitForURL(/portal/, { timeout: 180000 });
      for (const s of r.seiten) {
        const antwort = await page.goto(`${BASIS}${s}`, { waitUntil: "load", timeout: 180000 });
        await page.waitForTimeout(1200);
        const name = `${r.key}${s.replace(/\//g, "_")}.png`;
        await page.screenshot({ path: `${OUT}${name}` });
        console.log(`${r.key} ${s} -> ${antwort?.status()} ${fehler.length ? "FEHLER: " + fehler.join(" | ") : "ok"}`);
        fehler.length = 0;
      }
    } catch (e) {
      console.log(`${r.key} FEHLGESCHLAGEN: ${String(e).slice(0, 300)}`);
    } finally {
      await ctx.close();
    }
  }
} finally {
  await browser.close();
}

